import{_ as a,o as p,c as o,a5 as s}from"./chunks/framework.Cooo9kuv.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"PS003-批量将psd转为jpg格式图片-单文件夹版","日期":"2026-04-11T00:00:00.000Z","修改日期":"2026-04-11T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["Bat批处理","Photoshop批处理"],"标签":["psd文件批量转jpg图片","psd转图片","不打开psd转图片"]},"headers":[],"relativePath":"md/Bat批处理/PS003-批量将psd转为jpg格式图片-单文件夹版.md","filePath":"md/Bat批处理/PS003-批量将psd转为jpg格式图片-单文件夹版.md"}'),r={name:"md/Bat批处理/PS003-批量将psd转为jpg格式图片-单文件夹版.md"};function n(e,t,g,d,l,i){return p(),o("div",null,[...t[0]||(t[0]=[s('<h2 id="psd文件批量转jpg图片-单文件夹版本【不支持子文件夹穿透】" tabindex="-1">psd文件批量转jpg图片-单文件夹版本【不支持子文件夹穿透】 <a class="header-anchor" href="#psd文件批量转jpg图片-单文件夹版本【不支持子文件夹穿透】" aria-label="Permalink to &quot;psd文件批量转jpg图片-单文件夹版本【不支持子文件夹穿透】&quot;">​</a></h2><p>这个批处理程序的主要功能是将程序所在文件夹下的所有 PSD 文件转换为指定大小的 jpg 图片。</p><p><strong>使用时将bat程序放在需要处理的文件夹下运行即可</strong></p><p>程序会查找文件夹下的所有 PSD 文件，将 PSD 文件转换为 JPG 图片，转换后的图片大小为 1920x1920 像素/分辨率（如果自己看得懂bat脚本可以自行修改分辨率）。</p><p>转换后的 JPG 图片将存储在与 PSD 文件相同的目录下，文件名与 PSD 文件名相同，只是扩展名为 .jpg。</p><p><strong>需要注意的是，程序依赖于 ImageMagick 工具，因此在运行程序之前，需要先安装 ImageMagick 并配置环境变量。</strong></p><p><strong>拿到文件后先按照说明安装此工具：</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250218094143173984290366011.png" alt=""></p><h3 id="📑-使用场景例子展示" tabindex="-1">📑 使用场景例子展示 <a class="header-anchor" href="#📑-使用场景例子展示" aria-label="Permalink to &quot;📑 使用场景例子展示&quot;">​</a></h3><p>A文件夹下有很多支持的文件，同时有B、C、D....等文件夹，B、C、D....等这些文件夹下边还有子文件夹，子文件夹下也有支持的文件。</p><p>【操作方法】：将程序放在A文件夹下则只处理A文件夹下所有psd文件，放在B文件夹下则只处理B文件夹下psd文件，程序只支持单独某个文件夹下所有psd文件，不支持子文件夹穿透处理。</p><h3 id="📑-bat程序下一步执行方法" tabindex="-1">📑 bat程序下一步执行方法 <a class="header-anchor" href="#📑-bat程序下一步执行方法" aria-label="Permalink to &quot;📑 bat程序下一步执行方法&quot;">​</a></h3><p>**▶ **使用时，<strong>键盘回车键（就是键盘上的 ENTER 键）</strong>“回车确认”是执行下一步的方法 ，</p><p>比如将路径复制到程序中后，回车键确认执行下一步，每一步输入后，回车键确认即可向下执行。</p><p><strong>▶ 注意：请先测试备份原文件再批量使用，以免造成不可逆损失！！！</strong></p><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250218094049173984284971755.png" alt=""></p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>：建议win7及以上64位win操作系统，mac系统需要定制。</p><p><strong>注意事项：bat程序原理上是支持</strong>win32位系统的，但不能完全确定。</p><p><strong>2、使用期限</strong>： 无需注册、无需密码、不绑定电脑、无使用时间限制</p><p><strong>3、如何安装</strong>：程序不需要安装，按照说明使用即可</p><p><strong>特别注意 - 特别声明</strong>：请先测试，注意备份原文件，避免不可逆损失，之后再批量使用</p></blockquote><p>📑 本工具下载地址</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1253.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1253.html</a></p>',22)])])}const c=a(r,[["render",n]]);export{_ as __pageData,c as default};
